  Object.defineProperty(window,'__binaryComparisonRender',{configurable:true,get:()=>renderComparison,set:fn=>{comparisonDelegate=typeof fn==='function'&&fn!==renderComparison?fn:null}});
  Object.defineProperty(window,'__pendingComparisonRender',{configurable:true,get:()=>renderPendingComparison,set:fn=>{pendingComparisonDelegate=typeof fn==='function'&&fn!==renderPendingComparison?fn:null}});
